require 'digest'
require 'fileutils'
require 'json'
require 'rubygems/package'
require 'tmpdir'

# Only metadata comes from the public repository. Every generated byte is a
# labelled synthetic preview fixture, including the deliberately invalid ZFS data.
class ImageRepositoryFixtures
  SOURCE_SHA256 = 'e4ff27cf6873bd18b91b8641ed2ebfb08b601122bc69c805b841f72a7b09b62b'.freeze
  SOURCE_URL = 'https://images.vpsadminos.org/v1/INDEX.json'.freeze
  CAPTURED_AT = '2026-11-10T14:10:21.949194Z'.freeze
  MARKER = "synthetic preview, not an OS image\n".freeze
  FORMATS = { 'tar' => 'image-archive.tar', 'zfs' => 'image-stream.tar' }.freeze
  FIELDS = %w[vendor variant arch distribution version].freeze
  COMPONENT = /\A[A-Za-z0-9][A-Za-z0-9_.-]*\z/
  DEFAULT_INDEX = File.expand_path('../fixtures/image-repository/INDEX.json', __dir__).freeze
  MODIFIED = '1970-01-01T00:00:01Z'.freeze
  Link = Struct.new(:target)

  def initialize(index_path = DEFAULT_INDEX)
    @source = File.binread(index_path)
    raise 'Public metadata snapshot digest differs' unless Digest::SHA256.hexdigest(@source) == SOURCE_SHA256

    @index = JSON.parse(@source)
    validate_index(@index)
  end

  def self.json(value)
    sorted = lambda do |v|
      case v
      when Hash then v.keys.sort.to_h { |key| [key, sorted.call(v.fetch(key))] }
      when Array then v.map { |entry| sorted.call(entry) }
      else v
      end
    end
    JSON.generate(sorted.call(value))
  end

  def tuple(image)
    FIELDS.map { |key| image.fetch(key) }.join('/')
  end

  def validate_index(index)
    raise 'Invalid catalog object' unless index.is_a?(Hash) && index['images'].is_a?(Array) && index['vendors'].is_a?(Hash)

    paths = {}
    index['images'].each do |image|
      raise 'Invalid image tuple' unless FIELDS.all? { |key| component?(image[key]) }
      raise 'Invalid image tags' unless image['tags'].is_a?(Array) && image['tags'].uniq == image['tags'] && image['tags'].all? { |tag| component?(tag) }
      raise 'Invalid image formats' unless image['image'].is_a?(Hash) && !image['image'].empty?

      image['image'].each do |format, path|
        canonical = "#{tuple(image)}/#{FORMATS[format]}"
        raise 'Unsafe or noncanonical image path' unless FORMATS.key?(format) && path == canonical
        raise 'Colliding image path' if paths.key?(path)

        paths[path] = true
      end
    end
    keys = index['images'].map { |image| tuple(image) }
    raise 'Duplicate image tuple' unless keys.uniq == keys

    index['vendors'].each do |vendor, variant|
      raise 'Invalid default alias' unless component?(vendor) && component?(variant)
      next if vendor == 'default' && index['images'].any? { |image| image['vendor'] == variant }
      next if index['images'].any? { |image| image['vendor'] == vendor && image['variant'] == variant }

      raise 'Default alias has no image target'
    end
    routes(index) # Reject tag/version/default alias collisions before writing.
    index
  end

  def component?(value)
    value.is_a?(String) && value.bytesize <= 255 && COMPONENT.match?(value)
  end

  def routes(index = @index)
    result = {}
    index['images'].each do |image|
      vendors = [image['vendor']]
      vendors << 'default' if index['vendors']['default'] == image['vendor']
      variants = [image['variant']]
      variants << 'default' if index['vendors'][image['vendor']] == image['variant']
      vendors.product(variants, [image['version'], *image['tags']].uniq).each do |vendor, variant, version|
        image['image'].each do |format, canonical|
          path = [vendor, variant, image['arch'], image['distribution'], version, FORMATS.fetch(format)].join('/')
          raise 'Conflicting native alias' if result.key?(path) && result[path] != canonical

          result[path] = canonical
        end
      end
    end
    result
  end

  def payload(image, format)
    text = MARKER + self.class.json(FIELDS.to_h { |key| [key, image.fetch(key)] }.merge('format' => format)) + "\n"
    return "NOT A ZFS STREAM\n#{text}".b if format == 'zfs'

    header = Gem::Package::TarHeader.new(name: 'SYNTHETIC-PREVIEW.txt', mode: 0o644, uid: 0, gid: 0,
                                         size: text.bytesize, mtime: 1, typeflag: '0', prefix: '').to_s
    header.b + text.b + ("\0" * ((512 - text.bytesize % 512) % 512 + 1024))
  end

  def source_manifest
    entries = @index['images'].flat_map do |image|
      image['image'].map do |format, path|
        bytes = payload(image, format)
        raise 'Synthetic payload exceeds 4 KiB' if bytes.bytesize > 4096

        { 'path' => path, 'format' => format, 'size' => bytes.bytesize, 'sha256' => Digest::SHA256.hexdigest(bytes) }
      end
    end
    total = entries.sum { |entry| entry.fetch('size') }
    raise 'Synthetic payload budget exceeds 2 MiB' if total > 2 * 1024 * 1024

    { 'schema' => 1, 'fixture' => 'synthetic-preview-catalog-v1', 'purpose' => MARKER.strip,
      'provenance' => { 'url' => SOURCE_URL, 'captured_at' => CAPTURED_AT, 'sha256' => SOURCE_SHA256,
                        'payloads_downloaded' => false, 'source_sizes_or_hashes' => false },
      'tuples' => @index['images'].length, 'routes' => routes.length, 'payload_bytes' => total, 'files' => entries }
  end

  def generate(output)
    files = { 'v1/INDEX.json' => @source, 'synthetic.json' => self.class.json(source_manifest) + "\n" }
    @index['images'].each do |image|
      image['image'].each { |format, path| files["v1/#{path}"] = payload(image, format) }
      image['tags'].each do |tag|
        next if tag == image['version']

        files["v1/#{[image['vendor'], image['variant'], image['arch'], image['distribution'], tag].join('/')}"] = Link.new(image['version'])
      end
    end
    @index['vendors'].each do |vendor, variant|
      path = vendor == 'default' ? 'v1/default' : "v1/#{vendor}/default"
      files[path] = Link.new(variant)
    end
    atomic_output(output, files)
    source_manifest
  end

  # Prepare a COMPLETE portable generation, never an overlay import. Existing
  # FileRefs and bytes are copied unchanged; import-generation itself enforces CAS.
  def prepare_union(export_path:, output:, expected_generation:, allow_default_transition: false)
    baseline = JSON.parse(read_regular(export_path, 'manifest.json'))
    raise 'Expected a demo portable export at the captured generation' unless baseline['schema'] == 1 && baseline['repository'] == 'demo' &&
                                                                            baseline['generation'] == expected_generation && component?(expected_generation)
    catalog = baseline.fetch('catalog')
    native = native_index(catalog)
    validate_index(native)
    raise 'Baseline INDEX digest differs' unless baseline['index_sha256'] == Digest::SHA256.hexdigest(self.class.json(native))

    expected_paths = {}
    expected_refs = {}
    catalog.fetch('images').each do |image|
      image.fetch('files').each do |format, ref|
        path = "#{tuple(image)}/#{FORMATS.fetch(format)}"
        expected_paths[path] = ref.fetch('id')
        expected_refs[ref.fetch('id')] = ref
      end
    end
    raise 'Incomplete portable paths/files' unless expected_paths == baseline['paths'] && expected_refs == baseline['files']
    raise 'Current tuple collides with representative fixture' unless (native['images'].map { |image| tuple(image) } & @index['images'].map { |image| tuple(image) }).empty?

    vendors = catalog.fetch('vendors').dup
    @index.fetch('vendors').each do |vendor, variant|
      if vendors.key?(vendor) && vendors[vendor] != variant
        raise 'Default transition must be explicitly accepted' unless vendor == 'default' && allow_default_transition
      end
      vendors[vendor] = variant
    end
    union = Marshal.load(Marshal.dump(catalog))
    union['vendors'] = vendors
    files = {}
    refs = baseline.fetch('files').dup
    refs.each do |file_id, ref|
      raise 'Unsafe stable file ID' unless component?(file_id) && ref['id'] == file_id

      bytes = read_regular(export_path, "files/#{file_id}")
      raise 'Existing payload integrity differs' unless bytes.bytesize == ref['size'] && Digest::SHA256.hexdigest(bytes) == ref['sha256']

      files["files/#{file_id}"] = bytes
    end
    @index['images'].each do |image|
      added = FIELDS.to_h { |key| [key, image.fetch(key)] }.merge('tags' => image.fetch('tags'), 'files' => {})
      image['image'].each do |format, path|
        bytes = payload(image, format)
        file_id = Digest::SHA256.hexdigest("synthetic-preview-catalog-v1\0#{SOURCE_SHA256}\0#{path}")[0, 32]
        raise 'Stable synthetic file ID collision' if refs.key?(file_id)

        ref = { 'id' => file_id, 'sha256' => Digest::SHA256.hexdigest(bytes), 'size' => bytes.bytesize,
                'format' => format, 'modified' => MODIFIED }
        refs[file_id] = ref
        added['files'][format] = ref
        files["files/#{file_id}"] = bytes
      end
      union['images'] << added
    end
    validate_index(native_index(union))
    generation = "preview-catalog-v1-#{Digest::SHA256.hexdigest(self.class.json(union))[0, 32]}"
    paths = {}
    union['images'].each { |image| image['files'].each { |format, ref| paths["#{tuple(image)}/#{FORMATS.fetch(format)}"] = ref['id'] } }
    manifest = { 'schema' => 1, 'repository' => 'demo', 'generation' => generation, 'catalog' => union,
                 'index_sha256' => Digest::SHA256.hexdigest(self.class.json(native_index(union))), 'paths' => paths, 'files' => refs }
    request = { 'request_id' => "preview-catalog-v1-#{Digest::SHA256.hexdigest(expected_generation + File.expand_path(output))[0, 32]}",
                'operation' => 'import-generation', 'repository' => 'demo',
                'params' => { 'path' => File.expand_path(output), 'generation' => expected_generation } }
    receipt = source_manifest.merge('baseline_generation' => expected_generation, 'generation' => generation,
                                    'previous_defaults' => catalog['vendors'], 'defaults' => vendors,
                                    'preserved_tuples' => catalog['images'].length, 'total_tuples' => union['images'].length,
                                    'preserved_file_ids' => baseline['files'].keys.sort, 'executed' => false)
    files.merge!('manifest.json' => self.class.json(manifest) + "\n", 'import-request.json' => self.class.json(request) + "\n",
                 'synthetic.json' => self.class.json(receipt) + "\n")
    atomic_output(output, files)
    receipt
  end

  def native_index(catalog)
    { 'vendors' => catalog.fetch('vendors'), 'images' => catalog.fetch('images').sort_by { |image| tuple(image) }.map do |image|
      FIELDS.to_h { |key| [key, image.fetch(key)] }.merge('tags' => image.fetch('tags').sort,
                                                      'image' => image.fetch('files').keys.to_h { |format| [format, "#{tuple(image)}/#{FORMATS.fetch(format)}"] })
    end }
  end

  def read_regular(root, relative)
    path = File.expand_path(root)
    raise 'Input root must be a real directory' unless File.directory?(path) && !File.symlink?(path)

    relative.split('/').each do |part|
      raise 'Unsafe input component' unless component?(part)

      path = File.join(path, part)
      raise 'Input symlink refused' if File.symlink?(path)
    end
    raise 'Input must be a regular bounded file' unless File.file?(path) && File.size(path) <= 64 * 1024 * 1024

    File.binread(path)
  end

  def atomic_output(output, files)
    output = File.expand_path(output)
    digest = Digest::SHA256.hexdigest(self.class.json(files.transform_values { |bytes| bytes.is_a?(Link) ? ['link', bytes.target] : Digest::SHA256.hexdigest(bytes) }))
    files = files.merge('COMPLETE' => "synthetic-preview-catalog-v1 #{digest}\n")
    if File.exist?(output) || File.symlink?(output)
      raise 'Output root must be a real directory' unless File.directory?(output) && !File.symlink?(output)
      expected = files.keys.flat_map do |relative|
        parts = relative.split('/')
        (1..parts.length).map { |length| parts.first(length).join('/') }
      end.uniq.sort
      found = []
      walk = lambda do |directory, prefix|
        Dir.children(directory).each do |name|
          relative = prefix.empty? ? name : "#{prefix}/#{name}"
          path = File.join(directory, name)
          found << relative
          walk.call(path, relative) if File.lstat(path).directory?
        end
      end
      walk.call(output, '')
      raise 'Unexpected fixture entries' unless found.sort == expected

      files.each do |relative, wanted|
        path = File.join(output, relative)
        valid = if wanted.is_a?(Link)
                  File.symlink?(path) && File.readlink(path) == wanted.target
                else
                  File.file?(path) && !File.symlink?(path) && File.binread(path) == wanted
                end
        raise "Existing fixture differs: #{relative}" unless valid
      end
      return
    end
    parent = File.dirname(output)
    raise 'Output parent must be a real directory' unless File.directory?(parent) && !File.symlink?(parent)

    temporary = Dir.mktmpdir('.image-repository-fixtures-', parent)
    begin
      files.each do |relative, bytes|
        path = File.join(temporary, relative)
        FileUtils.mkdir_p(File.dirname(path), mode: 0o700)
        if bytes.is_a?(Link)
          File.symlink(bytes.target, path)
        else
          File.open(path, File::WRONLY | File::CREAT | File::EXCL, 0o600) { |file| file.write(bytes); file.fsync }
        end
      end
      files.keys.map { |path| File.dirname(path) }.uniq.sort.reverse_each do |directory|
        File.open(File.join(temporary, directory)) { |file| file.fsync }
      end
      File.open(temporary) { |directory| directory.fsync }
      File.rename(temporary, output)
      File.open(parent) { |directory| directory.fsync }
    ensure
      FileUtils.remove_entry(temporary) if File.exist?(temporary)
    end
  end
end

if $PROGRAM_NAME == __FILE__
  abort 'Usage: image-repository-fixtures.rb OUTPUT_DIRECTORY' unless ARGV.length == 1
  puts ImageRepositoryFixtures.json(ImageRepositoryFixtures.new.generate(ARGV.first))
end
